        this.spoutBuffer = null;;
        this.zerodBFS = 1.;                                    
        this.ksmps = 128;
        this.csound_input_channel_n = 1;
        this.csound_output_channel_n = 2;
        this.is_playing = false;
        this.format_validated = false;
        this.has_audio_input = false;
